#include <iostream>#include <vector>#include <string>using namespace std;int main() {    vector<string> personagens;    string nome;    int opcao;    cout << "=== SISTEMA DE PERSONAGENS 📦 ===" << endl;    do {        cout << endl;        cout << "1 - Adicionar personagem" << endl;        cout << "2 - Mostrar personagens" << endl;        cout << "0 - Sair" << endl;        cout << "Opcao: ";        cin >> opcao;        if (opcao == 1) {            cout << "Digite o nome do personagem: ";            cin >> nome;            personagens.push_back(nome);            cout << "Personagem adicionado com sucesso 😄" << endl;        }        else if (opcao == 2) {            cout << endl;            cout << "=== LISTA DE PERSONAGENS ===" << endl;            if (personagens.empty()) {                cout << "Nenhum personagem adicionado 😅" << endl;            } else {                for (int i = 0; i < personagens.size(); i++) {                    cout << i << " - " << personagens[i] << endl;                }            }        }        else if (opcao == 0) {            cout << "Saindo... 👋" << endl;        }        else {            cout << "Opcao invalida 😅" << endl;        }    } while (opcao != 0);    return 0;}